// ============================================================
// CONFIG - único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  nomeEmpresa: "Manduca Piscinas",
  nomeDestinatario: "Tais",
  email: "SUBSTITUA_PELO_EMAIL_DESTINO",
  titulo: "Pendências até ontem",
  assunto: "Pendências até ontem - Manduca Piscinas",
  logoUrl: "SUBSTITUA_PELA_URL_PUBLICA_DO_LOGO_PNG",
  fusoHoras: -3,
  maxItensPorLista: 20,
  nomesIgnorados: ["CONSUMIDOR FINAL"],
  clientesNaoFaturados: [],
  statusOrcamento: ["ORCAMENTO", "ORÇAMENTO"],
  statusVenda: ["VENDA"],
  statusOS: ["OS", "O.S.", "ORDEM DE SERVICO", "ORDEM DE SERVIÇO", "VENDA"],
  nodes: {
    vendas: "Vendas da Semana",
    os: "O.S. da Semana",
    pagar: "Contas a Pagar da Semana",
    receber: "Contas a Receber da Semana"
  },
  aliases: {
    numero: ["numero"],
    data: ["data"],
    status: ["status"],
    cliente: ["cliente"],
    vendedor: ["vendedor"],
    valor: ["valor"],
    temNf: ["tem_nf"],
    nfNumero: ["nf_numero"],
    documento: ["lancamento", "documento"],
    parcela: ["parcela"],
    vencimento: ["datavencimento", "vencimento"],
    pagamento: ["datapagamento"],
    nomePagar: ["nomfornece", "nome"],
    saldoPagar: ["remanescente", "saldo", "valor"],
    nomeReceber: ["nomcliente", "nome"],
    saldoReceber: ["saldo", "remanescente", "valor"]
  }
};

// ============================================================
// Utilitários (sem toLocaleString: o sandbox não suporta)
// ============================================================
const A = CONFIG.aliases;
const F = "font-family:Inter, Arial, Helvetica, sans-serif;";

function txt(v) { return v === null || v === undefined ? "" : String(v).trim(); }
function norm(v) { return txt(v).toUpperCase(); }
function num(v) {
  if (typeof v === "number") return isNaN(v) ? 0 : v;
  let s = txt(v);
  if (s.indexOf(",") >= 0) s = s.replace(/\./g, "").replace(",", ".");
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}
function dia(v) {
  const s = txt(v).slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) && s !== "1900-01-01" ? s : "";
}
function br(d) { return d ? d.slice(8, 10) + "/" + d.slice(5, 7) + "/" + d.slice(0, 4) : "-"; }
function moeda(v) {
  const n = Math.round(num(v) * 100) / 100;
  const p = Math.abs(n).toFixed(2).split(".");
  return (n < 0 ? "-" : "") + "R$ " + p[0].replace(/\B(?=(\d{3})+(?!\d))/g, ".") + "," + p[1];
}
function escaparHtml(texto) {
  return txt(texto).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
}
function diasEntre(a, b) { return Math.round((Date.parse(b + "T00:00:00Z") - Date.parse(a + "T00:00:00Z")) / 86400000); }
function pega(linha, nomes) {
  for (let i = 0; i < nomes.length; i++) {
    const v = linha[nomes[i]];
    if (v !== undefined && v !== null && txt(v) !== "") return v;
  }
  return "";
}
function soma(lista) { return lista.reduce(function (s, r) { return s + r.valor; }, 0); }

// ============================================================
// Leitura dos quatro relatórios (o Data Lab devolve { dados: [ { dados: [linhas], erros } ] })
// ============================================================
const avisos = [];
function lerRelatorio(nome) {
  let base = null;
  try { base = $node[nome] ? $node[nome].json : null; } catch (e) { base = null; }
  const linhas = [];
  function abrir(o) {
    if (Array.isArray(o)) { o.forEach(abrir); return; }
    if (!o || typeof o !== "object") return;
    if (Array.isArray(o.erros) && o.erros.length) avisos.push(nome + ": " + o.erros.map(function (e) { return typeof e === "string" ? e : JSON.stringify(e); }).join("; "));
    if (Array.isArray(o.dados)) { o.dados.forEach(abrir); return; }
    if (Object.keys(o).length) linhas.push(o);
  }
  if (base === null) avisos.push(nome + ": relatório não encontrado no flow.");
  abrir(base);
  console.log(nome + ": " + linhas.length + " linhas" + (linhas.length ? " | colunas: " + Object.keys(linhas[0]).join(", ") : ""));
  return linhas;
}

let agora = Date.now();
try { if ($now && !isNaN(Date.parse($now))) agora = Date.parse($now); } catch (e) { }
const hoje = new Date(agora + CONFIG.fusoHoras * 3600000).toISOString().slice(0, 10);

const ignorados = CONFIG.nomesIgnorados.map(norm);
const naoFaturados = CONFIG.clientesNaoFaturados.map(norm).filter(function (s) { return s; });
const stOrc = CONFIG.statusOrcamento.map(norm);
function ignorado(nome) { return ignorados.indexOf(norm(nome)) >= 0; }
function contratoNaoFaturado(nome) { const n = norm(nome); return naoFaturados.some(function (s) { return n.indexOf(s) >= 0; }); }
function temNota(l) {
  const t = norm(pega(l, A.temNf));
  if (t === "SIM" || t === "S") return true;
  if (t === "NÃO" || t === "NAO" || t === "N") return false;
  return txt(pega(l, A.nfNumero)) !== "";
}

// Vendas e O.S.: orçamento até ontem / documento não faturado até ontem
function movimentos(linhas, statusDocumento) {
  const stDoc = statusDocumento.map(norm);
  const orc = [], naoFaturado = [];
  linhas.forEach(function (l) {
    const d = dia(pega(l, A.data));
    if (!d || d >= hoje) return;
    const cliente = txt(pega(l, A.cliente));
    if (ignorado(cliente)) return;
    const st = norm(pega(l, A.status));
    const r = { numero: txt(pega(l, A.numero)), data: d, nome: cliente, vendedor: txt(pega(l, A.vendedor)), valor: num(pega(l, A.valor)), dias: diasEntre(d, hoje) };
    if (stOrc.indexOf(st) >= 0) orc.push(r);
    else if (stDoc.indexOf(st) >= 0 && !temNota(l) && !contratoNaoFaturado(cliente)) naoFaturado.push(r);
  });
  const ordem = function (a, b) { return a.data < b.data ? -1 : a.data > b.data ? 1 : (num(a.numero) - num(b.numero)); };
  orc.sort(ordem);
  naoFaturado.sort(ordem);
  return { orc: orc, naoFaturado: naoFaturado };
}

// Contas: em aberto, vencidas até ontem / vencendo hoje
function contas(linhas, aliasNome, aliasSaldo) {
  const vencidas = [], deHoje = [];
  linhas.forEach(function (l) {
    const v = dia(pega(l, A.vencimento));
    if (!v || v > hoje) return;
    if (dia(pega(l, A.pagamento))) return;
    const nome = txt(pega(l, aliasNome));
    if (ignorado(nome)) return;
    const saldo = num(pega(l, aliasSaldo));
    if (saldo <= 0) return;
    const parcela = txt(pega(l, A.parcela));
    const r = { documento: txt(pega(l, A.documento)) + (parcela ? " · " + parcela : ""), nome: nome, vencimento: v, valor: saldo, dias: diasEntre(v, hoje) };
    (v < hoje ? vencidas : deHoje).push(r);
  });
  vencidas.sort(function (a, b) { return a.vencimento < b.vencimento ? -1 : a.vencimento > b.vencimento ? 1 : b.valor - a.valor; });
  deHoje.sort(function (a, b) { return b.valor - a.valor; });
  return { vencidas: vencidas, hoje: deHoje };
}

const vendas = movimentos(lerRelatorio(CONFIG.nodes.vendas), CONFIG.statusVenda);
const os = movimentos(lerRelatorio(CONFIG.nodes.os), CONFIG.statusOS);
const pagar = contas(lerRelatorio(CONFIG.nodes.pagar), A.nomePagar, A.saldoPagar);
const receber = contas(lerRelatorio(CONFIG.nodes.receber), A.nomeReceber, A.saldoReceber);

const COL_MOV = [
  { t: "Nº", c: "numero", w: "64" },
  { t: "Data", c: "data", w: "78", f: br },
  { t: "Cliente", c: "nome", forte: true },
  { t: "Vendedor", c: "vendedor", w: "96" },
  { t: "Valor", c: "valor", w: "92", f: moeda, dir: true }
];
function colContas(rotulo, vencidas) {
  const col = [
    { t: rotulo, c: "nome", forte: true },
    { t: "Lançamento", c: "documento", w: "96" }
  ];
  if (vencidas) col.push({ t: "Venc.", c: "vencimento", w: "78", f: br });
  col.push({ t: "Valor", c: "valor", w: "92", f: moeda, dir: true });
  return col;
}

const grupos = [
  { id: "orcVenda", sec: "Vendas", rotulo: "Orçamentos de venda", desc: "lançados até ontem, não viraram venda", itens: vendas.orc, col: COL_MOV, idade: "lançado há" },
  { id: "orcOS", sec: "O.S.", rotulo: "Orçamentos de O.S.", desc: "lançados até ontem, não aprovados", itens: os.orc, col: COL_MOV, idade: "lançado há" },
  { id: "vendaNaoFaturada", sec: "Vendas", rotulo: "Vendas não faturadas", desc: "lançadas até ontem, não faturadas", itens: vendas.naoFaturado, col: COL_MOV, idade: "lançada há" },
  { id: "osNaoFaturada", sec: "O.S.", rotulo: "O.S. não faturadas", desc: "lançadas até ontem, não faturadas", itens: os.naoFaturado, col: COL_MOV, idade: "lançada há" },
  { id: "pagarVenc", sec: "A pagar", rotulo: "A pagar vencidas", desc: "em aberto, vencimento até ontem", itens: pagar.vencidas, col: colContas("Fornecedor", true), idade: "venceu há", alerta: true },
  { id: "receberVenc", sec: "A receber", rotulo: "A receber vencidas", desc: "em aberto, vencimento até ontem", itens: receber.vencidas, col: colContas("Cliente", true), idade: "venceu há", alerta: true },
  { id: "pagarHoje", sec: "A pagar", rotulo: "A pagar hoje", desc: "em aberto, vencem hoje", itens: pagar.hoje, col: colContas("Fornecedor", false) },
  { id: "receberHoje", sec: "A receber", rotulo: "A receber hoje", desc: "em aberto, vencem hoje", itens: receber.hoje, col: colContas("Cliente", false) }
];

// ============================================================
// HTML (mesmo padrão visual dos e-mails Waipe)
// ============================================================
function montarPagina(titulo, preheader, miolo) {
  let h = "";
  h += "<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'>";
  h += "<meta name='color-scheme' content='light dark'><meta name='supported-color-schemes' content='light dark'>";
  h += "<title>" + escaparHtml(titulo) + "</title>";
  h += "<style>body{margin:0;padding:0;-webkit-text-size-adjust:100%;}a{color:#303030;}";
  h += "@media only screen and (max-width:620px){.wrap{width:100% !important;}.px{padding-left:16px !important;padding-right:16px !important;}.kpi{display:block !important;width:100% !important;padding:0 0 8px 0 !important;}.h1{font-size:24px !important;line-height:30px !important;}.hide-sm{display:none !important;}}";
  h += "@media (prefers-color-scheme: dark){.bg-page{background:#111827 !important;}.bg-card{background:#1F2937 !important;}.bg-soft{background:#27303F !important;}.t-strong{color:#F3F4F6 !important;}.t-muted{color:#9CA3AF !important;}.bd{border-color:#374151 !important;}.eyebrow{color:#D4B25A !important;}td[bgcolor='#F1F2EC']{background:#2A2E24 !important;}.kpi-ol{color:#C9CFB4 !important;}td[bgcolor='#FEF2F2']{background:#3A2422 !important;}.kpi-al{color:#FCA5A5 !important;}td[bgcolor='#FBF6EA']{background:#2F2A1E !important;}.logo{filter:invert(1) brightness(1.1) !important;}}";
  h += "</style></head>";
  h += "<body style='margin:0;padding:0;background:#F3F4F6;' class='bg-page'>";
  h += "<span style='display:none;font-size:1px;color:#F3F4F6;line-height:1px;max-height:0;max-width:0;opacity:0;overflow:hidden;mso-hide:all;'>" + escaparHtml(preheader) + "</span>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' bgcolor='#F3F4F6' class='bg-page' style='background:#F3F4F6;'><tr><td align='center' style='padding:32px 12px;'>";
  h += "<!--[if mso]><table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0'><tr><td><![endif]-->";
  h += "<table role='presentation' width='600' cellpadding='0' cellspacing='0' border='0' class='wrap' style='width:600px;max-width:600px;'>";
  h += "<tr><td class='px' style='padding:0 8px 16px 8px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  // Marca: ícone (imagem pública em CONFIG.logoUrl) + "waipe" em texto, como no modelo aprovado
  h += "<td valign='middle' style='padding:0;'><a href='https://waipe.com.br' style='text-decoration:none;'><table role='presentation' cellpadding='0' cellspacing='0' border='0'><tr>";
  if (CONFIG.logoUrl && CONFIG.logoUrl.indexOf("SUBSTITUA") < 0) {
    h += "<td valign='middle' style='padding:0 8px 0 0;font-size:0;line-height:0;'><img src='" + escaparHtml(CONFIG.logoUrl) + "' width='28' height='28' alt='' class='logo' style='display:block;width:28px;height:28px;border:0;outline:none;text-decoration:none;'></td>";
  }
  h += "<td valign='middle' class='t-strong' style='" + F + "font-size:24px;font-weight:600;color:#303030;letter-spacing:-0.3px;mso-line-height-rule:exactly;line-height:28px;'>waipe</td>";
  h += "</tr></table></a></td>";
  h += "<td align='right' class='t-muted' style='" + F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + escaparHtml(CONFIG.nomeEmpresa) + "<br>Relatório diário &middot; " + br(hoje) + "</td>";
  h += "</tr></table></td></tr>";
  h += "<tr><td bgcolor='#FEFEFE' class='bg-card bd' style='background:#FEFEFE;border:1px solid #E5E7EB;border-radius:8px;overflow:hidden;'>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td height='4' bgcolor='#303030' style='height:4px;font-size:0;line-height:0;background:#303030;border-radius:8px 8px 0 0;'>&nbsp;</td></tr></table>";
  h += miolo;
  h += "</td></tr>";
  h += "<tr><td class='px' align='center' style='padding:24px 24px 0 24px;'>";
  h += "<p class='t-muted' style='margin:0 0 8px 0;" + F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:18px;'>Enviado automaticamente pelo Waipe todos os dias às 08:00 para " + escaparHtml(CONFIG.nomeEmpresa) + ".</p>";
  h += "<p class='t-muted' style='margin:0;" + F + "font-size:12px;color:#9CA3AF;mso-line-height-rule:exactly;line-height:18px;'>Londrisoft &middot; Londrina, PR &middot; Brasil</p>";
  h += "</td></tr></table>";
  h += "<!--[if mso]></td></tr></table><![endif]-->";
  h += "</td></tr></table></body></html>";
  return h;
}

function cabecalho(texto) {
  let h = "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td class='px' style='padding:32px 32px 8px 32px;'>";
  h += "<p class='eyebrow' style='margin:0 0 8px 0;" + F + "font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#8E6A1F;mso-line-height-rule:exactly;line-height:16px;'>Rotina da manhã</p>";
  h += "<h1 class='h1 t-strong' style='margin:0 0 12px 0;" + F + "font-size:28px;font-weight:bold;color:#303030;letter-spacing:-0.5px;mso-line-height-rule:exactly;line-height:34px;'>" + escaparHtml(CONFIG.titulo) + "</h1>";
  h += "<p class='t-muted' style='margin:0;" + F + "font-size:15px;color:#4B5563;mso-line-height-rule:exactly;line-height:23px;'>" + texto + "</p>";
  h += "</td></tr></table>";
  return h;
}

// Cartão de totalizador: oliva quando há pendência, vermelho suave para vencidas, cinza quando zerado
function cartao(g, lado) {
  const qtd = g.itens.length;
  let fundo = "#F9FAFB", cls = "bg-soft", corN = "#303030", clsN = "t-strong", corT = "#4B5563", clsT = "t-muted";
  if (qtd > 0 && g.alerta) { fundo = "#FEF2F2"; cls = ""; corN = "#B42828"; clsN = "kpi-al"; corT = "#B42828"; clsT = "kpi-al"; }
  else if (qtd > 0) { fundo = "#F1F2EC"; cls = ""; corN = "#5A6344"; clsN = "kpi-ol"; corT = "#5A6344"; clsT = "kpi-ol"; }
  const pad = lado === "e" ? "padding:0 6px 12px 0;" : "padding:0 0 12px 6px;";
  let h = "<td class='kpi' width='50%' valign='top' style='" + pad + "'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='" + fundo + "' class='" + cls + "' style='background:" + fundo + ";border-radius:8px;padding:16px;'>";
  h += "<p class='" + clsN + "' style='margin:0;" + F + "font-size:30px;font-weight:bold;color:" + corN + ";mso-line-height-rule:exactly;line-height:34px;'>" + qtd + "</p>";
  h += "<p class='" + clsT + "' style='margin:4px 0 0 0;" + F + "font-size:13px;font-weight:bold;color:" + corT + ";mso-line-height-rule:exactly;line-height:18px;'>" + escaparHtml(g.rotulo) + "</p>";
  h += "<p class='" + clsT + "' style='margin:2px 0 0 0;" + F + "font-size:12px;color:" + corT + ";mso-line-height-rule:exactly;line-height:16px;'>" + (qtd > 0 ? moeda(soma(g.itens)) : "Nada pendente") + "</p>";
  h += "</td></tr></table></td>";
  return h;
}

function blocoKpi(titulo, gEsq, gDir) {
  let h = "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td class='px' style='padding:16px 32px 0 32px;'>";
  h += "<p class='t-muted' style='margin:0 0 8px 0;" + F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;'>" + titulo + "</p>";
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>" + cartao(gEsq[0], "e") + cartao(gDir[0], "d") + "</tr><tr>" + cartao(gEsq[1], "e") + cartao(gDir[1], "d") + "</tr></table>";
  h += "</td></tr></table>";
  return h;
}

function th(c, primeira, ultima) {
  const raio = primeira ? "border-radius:8px 0 0 0;" : ultima ? "border-radius:0 8px 0 0;" : "";
  const pad = primeira ? "padding:10px 8px 10px 16px;" : ultima ? "padding:10px 16px 10px 8px;" : "padding:10px 8px;";
  return "<td bgcolor='#F9FAFB' class='bg-soft t-muted" + (c.forte ? "" : " hide-sm") + "'" + (c.w ? " width='" + c.w + "'" : "") + (c.dir ? " align='right'" : "") + " style='background:#F9FAFB;" + pad + F + "font-size:11px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#6B7280;" + raio + "'>" + c.t + "</td>";
}

function tabela(g) {
  const qtd = g.itens.length;
  let h = "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'>";
  h += "<tr><td class='px' style='padding:28px 32px 0 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr>";
  h += "<td class='t-strong' style='" + F + "font-size:16px;font-weight:bold;color:#303030;mso-line-height-rule:exactly;line-height:22px;'>" + escaparHtml(g.rotulo) + " (" + qtd + ")</td>";
  h += "<td align='right' class='t-muted' style='" + F + "font-size:12px;color:#6B7280;mso-line-height-rule:exactly;line-height:16px;'>" + escaparHtml(g.desc) + "</td>";
  h += "</tr></table></td></tr>";
  h += "<tr><td class='px' style='padding:12px 32px 0 32px;'>";
  if (!qtd) {
    h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' class='bd' style='border:1px solid #E5E7EB;border-radius:8px;'><tr><td class='t-muted' style='padding:14px 16px;" + F + "font-size:13px;color:#4B5563;'>&#10003; Nada pendente.</td></tr></table>";
    h += "</td></tr></table>";
    return h;
  }
  h += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0' class='bd' style='border:1px solid #E5E7EB;border-radius:8px;'><tr>";
  g.col.forEach(function (c, i) { h += th(c, i === 0, i === g.col.length - 1); });
  h += "</tr>";
  g.itens.slice(0, CONFIG.maxItensPorLista).forEach(function (r) {
    h += "<tr>";
    g.col.forEach(function (c, i) {
      const pad = i === 0 ? "padding:9px 8px 9px 16px;" : i === g.col.length - 1 ? "padding:9px 16px 9px 8px;" : "padding:9px 8px;";
      const valor = c.f ? c.f(r[c.c]) : escaparHtml(r[c.c]);
      let extra = "";
      if (c.forte && g.idade) extra = "<br><span class='t-muted' style='font-size:12px;font-weight:normal;color:#9CA3AF;'>" + g.idade + " " + r.dias + (r.dias === 1 ? " dia" : " dias") + "</span>";
      h += "<td class='bd " + (c.forte ? "t-strong" : "t-muted hide-sm") + "' valign='top'" + (c.dir ? " align='right'" : "") + " style='border-top:1px solid #F3F4F6;" + pad + F + "font-size:13px;" + (c.forte || c.dir ? "font-weight:bold;color:#303030;" : "color:#4B5563;") + "mso-line-height-rule:exactly;line-height:18px;'>" + (valor || "-") + extra + "</td>";
    });
    h += "</tr>";
  });
  if (qtd > CONFIG.maxItensPorLista) {
    const resto = g.itens.slice(CONFIG.maxItensPorLista);
    h += "<tr><td colspan='" + g.col.length + "' bgcolor='#F9FAFB' class='bg-soft t-muted bd' style='background:#F9FAFB;border-top:1px solid #F3F4F6;padding:10px 16px;" + F + "font-size:12px;color:#6B7280;border-radius:0 0 8px 8px;'>e mais " + resto.length + " (" + moeda(soma(resto)) + ")</td></tr>";
  }
  h += "</table></td></tr></table>";
  return h;
}

const porId = {};
grupos.forEach(function (g) { porId[g.id] = g; });
const totalPendencias = grupos.reduce(function (s, g) { return s + g.itens.length; }, 0);

let miolo = cabecalho("Bom dia, " + escaparHtml(CONFIG.nomeDestinatario) + ". " + (totalPendencias ? "Este é o resumo do que ficou em aberto até ontem e do que vence hoje. Os números de cima são os totais; logo abaixo vem a lista de cada um." : "Nada ficou em aberto até ontem e nada vence hoje. Bom trabalho!"));
if (avisos.length) {
  miolo += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td class='px' style='padding:16px 32px 0 32px;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td bgcolor='#FBF6EA' style='background:#FBF6EA;border-radius:8px;padding:12px 16px;" + F + "font-size:12px;color:#8E6A1F;line-height:18px;'><b>Atenção:</b> " + avisos.map(escaparHtml).join("<br>") + "</td></tr></table></td></tr></table>";
}
miolo += blocoKpi("Vendas e O.S. até ontem", [porId.orcVenda, porId.vendaNaoFaturada], [porId.orcOS, porId.osNaoFaturada]);
miolo += blocoKpi("Financeiro em aberto", [porId.pagarVenc, porId.pagarHoje], [porId.receberVenc, porId.receberHoje]);
grupos.forEach(function (g) { miolo += tabela(g); });
miolo += "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' border='0'><tr><td style='padding:0 0 32px 0;font-size:0;line-height:0;'>&nbsp;</td></tr></table>";

const preheader = vendas.orc.length + " orçamentos, " + vendas.naoFaturado.length + " vendas não faturadas, " + os.naoFaturado.length + " O.S. não faturadas, " + (pagar.vencidas.length + pagar.hoje.length) + " contas a pagar e " + (receber.vencidas.length + receber.hoje.length) + " a receber.";
const html = montarPagina(CONFIG.titulo + " - Waipe", preheader, miolo);

const totais = {};
grupos.forEach(function (g) { totais[g.id] = { quantidade: g.itens.length, valor: Math.round(soma(g.itens) * 100) / 100 }; });

return [{ json: { assunto: CONFIG.assunto + " - " + br(hoje), html: html, email: CONFIG.email, hoje: hoje, totais: totais, avisos: avisos } }];
